tool_input_args.value:
awk -F, '
  NR>1 && $7=="won" && ($2=="James Okafor" || $2=="Sofia Delgado") {
    sum += $5; reps[$2] += $5
  }
  NR>1 && $7=="won" { total += $5 }
  END {
    for (r in reps) printf "  %s: $%d\n", r, reps[r]
    printf "  Combined (James + Sofia): $%d\n", sum
    printf "  All reps total won: $%d\n", total
  }
' data/sales_q3.csv
